    uint z0;          // first row of this dispatch (a big field is split into row bands)
    uint rows;        // rows in this dispatch
    uint octaves;
    uint kind;        // 0 fbm (rolling), 1 ridged, 2 billow
    uint basis;       // 0 perlin, 1 simplex
